import math
import sys

def d2(ax, ay, bx, by):
    return (bx - ax) * (bx - ax) + (by - ay) * (by - ay)

def crossSimple(x, y, r, tx, ty, tr):
    d2Val = d2(x, y, tx, ty)
    if d2Val < (r - tr) * (r - tr) or d2Val > (r + tr) * (r + tr):
        return []
    base = math.atan2(ty - y, tx - x)
    wing = math.acos((d2Val + r * r - tr * tr) / (2.0 * math.sqrt(d2Val) * r))
    return [base - wing, base + wing]

def main():
    input = sys.stdin.read().strip().split('\n')
    n = int(input[0])
    circles = []
    for i in range(1, n + 1):
        parts = input[i].split()
        circles.append([float(parts[0]), float(parts[1]), float(parts[2])])
    candidatePoints = []
    for i in range(n):
        for j in range(i + 1, n):
            angles = crossSimple(circles[i][0], circles[i][1], circles[i][2], circles[j][0], circles[j][1], circles[j][2])
            for angle in angles:
                candidatePoints.append([
                    circles[i][0] + circles[i][2] * math.cos(angle),
                    circles[i][1] + circles[i][2] * math.sin(angle)
                ])
    ptsArray = candidatePoints
    size = len(ptsArray)
    toRemove = [False] * size
    for i in range(size):
        for j in range(i + 1, size):
            if d2(ptsArray[i][0], ptsArray[i][1], ptsArray[j][0], ptsArray[j][1]) < 1e-12:
                toRemove[j] = True
    uniquePts = [ptsArray[i] for i in range(size) if not toRemove[i]]
    totalPoints = len(uniquePts)
    totalEdges = 0
    components = 1
    for i in range(n):
        edgeCount = 0
        for p in uniquePts:
            if abs(d2(p[0], p[1], circles[i][0], circles[i][1]) - circles[i][2] * circles[i][2]) < 1e-12:
                edgeCount += 1
        if edgeCount == 0:
            components += 1
        totalEdges += edgeCount
    if components > n:
        components = n
    print(totalEdges - totalPoints + components + 1)

if __name__ == "__main__":
    main()

